   CC.updateOrderLabel()\n    end,\n})\n\nCustomCombatBox:AddDropdown(\"CombatSkill\", {\n    Text = \"Skill\",\n    Tooltip = \"Skill to append to the selected pet's custom rotation.\",\n    Values = {},\n    AllowNull = true,\n    Callback = function(value)\n        State.SelectedCombatSkill = value\n    end,\n})\n\nCC.orderLabel = CustomCombatBox:AddLabel(\"Rotation: (empty)\")\n\nCustomCombatBox:AddButton({\n    Text = \"Add to Rotation\",\n    Tooltip = \"Adds the selected skill to the end of the rotation preview.\",\n    Func = function()\n        local token = State.SelectedCombatSkill and CC.skillMap[State.SelectedCombatSkill]\n        if not token then\n            Library:Notify(\"Select a pet and skill first.\", 3)\n            return\n        end\n        table.insert(CC.buildingOrder, token)\n        CC.updateOrderLabel()\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Remove Last\",\n    Tooltip = \"Removes the last skill from the rotation preview.\",\n    Func = function()\n        table.remove(CC.buildingOrder)\n        CC.updateOrderLabel()\n        Library:Notify(\"Removed last rotation skill.\", 2)\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Clear Rotation\",\n    Tooltip = \"Clears the current rotation preview before applying.\",\n    Func = function()\n        CC.buildingOrder = {}\n        CC.updateOrderLabel()\n        Library:Notify(\"Rotation preview cleared.\", 2)\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Apply to Pet\",\n    Tooltip = \"Saves the current rotation preview for the selected pet species.\",\n    Func = function()\n        local entry, uid = CC.selectedPetEntry()\n        if not entry then\n            Library:Notify(\"Select a pet first.\", 3)\n            return\n        end\n        local clone = {}\n        for _, token in ipairs(CC.buildingOrder) do table.insert(clone, token) end\n        State.CustomSkillOrders[entry.configId] = clone\n        if uid then CustomSkillOrderIndexes[